            seen|=set(run); runs.append(run)
        for run in runs:
            if len(run)<2: continue
            s,e=run[0],run[-1]
            n2=(s[0]-d[0],s[1]-d[1])
            while 0<=n2[0]<H and 0<=n2[1]<W and g[n2[0]][n2[1]]==bg:
                o[n2[0]][n2[1]]=c; n2=(n2[0]-d[0],n2[1]-d[1])
            n2=(e[0]+d[0],e[1]+d[1])
            while 0<=n2[0]<H and 0<=n2[1]<W and g[n2[0]][n2[1]]==bg:
                o[n2[0]][n2[1]]=c; n2=(n2[0]+d[0],n2[1]+d[1])
    return o
print({n:solve(G[f'Demo pair {n} input'])==G[f'Demo pair {n} output'] for n in [2,3,4]})
